import{SIDE_IR_SERVICE_SOURCE}from'./side-ir-service-source.js';
const BANK={"r1-one":[{"id":408991,"title":["側面IRセンサーと本体の型を確認する","Identify the side IR sensor and housing","Určení bočního IR senzoru a pouzdra","Seitlichen IR-Sensor und Gehäuse bestimmen"],"body":["側面のIR基板を交換します。Nextruder内のセンサーとは別の部品です。交換用IR基板を用意し、実物のカバーとねじ位置を写真で確認してください。旧型の片側ねじ式、両側ねじ式、スイッチ付きOne+では、カバーと取付けねじが異なります。","Replace the IR board in the side sensor, which is separate from the sensor inside the Nextruder. Have the replacement board ready and compare the actual cover and screw locations with the photos. The early single-side cover, later two-screw cover and switched One+ housing use different cover and mounting hardware.","Vyměňuje se IR deska bočního senzoru, nikoli senzor uvnitř Nextruderu. Připravte náhradní desku a porovnejte skutečný kryt a polohy šroubů s fotografiemi. Starší kryt s jedním uvolňovaným šroubem, novější kryt se dvěma šrouby a pouzdro One+ s přepínačem mají odlišné upevnění.","Ersetzt wird die IR-Platine des seitlichen Sensors, nicht der Sensor im Nextruder. Ersatzplatine bereitlegen und Abdeckung sowie Schraubenpositionen am Drucker mit den Fotos vergleichen. Frühe einseitig gelöste Abdeckung, spätere Abdeckung mit zwei Schrauben und One+ mit Schalter haben unterschiedliche Befestigungen."]},{"id":409081,"title":["工具と交換基板を用意する","Prepare tools and the replacement board","Příprava nářadí a náhradní desky","Werkzeuge und Ersatzplatine bereitlegen"],"body":["2.5 mmと1.5 mmの六角レンチ、T10 Torxを用意します。ナイロンリベットの頭を持ち上げるには薄刃ニッパーがあると便利です。リベットを切断するためには使いません。外したねじを種類ごとに保管できる場所も用意してください。","Prepare 2.5 mm and 1.5 mm hex keys and a T10 Torx key. Flush cutters can help lift the nylon rivet heads; use them to lift, not cut. Set aside a place to keep the different removed screws separate.","Připravte imbusy 2,5 a 1,5 mm a klíč Torx T10. Štípací kleště mohou pomoci nadzvednout hlavy nylonových nýtů; nýty s nimi nestříhejte. Připravte místo pro oddělené uložení různých vyjmutých šroubů.","Innensechskantschlüssel 2,5 und 1,5 mm sowie Torx T10 bereitlegen. Ein Seitenschneider hilft beim Anheben der Nylon-Nietköpfe; die Niete damit nicht durchtrennen. Unterschiedliche ausgebaute Schrauben getrennt ablegen."]},{"id":409117,"title":["フィラメントを抜き、十分に冷ます","Unload filament and let the printer cool","Vysunutí filamentu a vychladnutí tiskárny","Filament entladen und Drucker abkühlen lassen"],"body":["ドアを閉め、実機の「フィラメント → フィラメント アンロード」でフィラメントを抜きます。スプールも外してください。「プレヒート → クールダウン」を選び、ノズルとベッドが室温まで下がるのを待ちます。","Close the door and use Filament → Unload Filament on the printer. Remove the filament and spool. Select Preheat → COOLDOWN and wait until the nozzle and bed have cooled to room temperature.","Zavřete dveře a na tiskárně zvolte Filament → Vyjmout filament. Vyjměte filament i cívku. Zvolte Předehřev → Zchladit a počkejte, až tryska i podložka vychladnou na pokojovou teplotu.","Tür schließen und am Drucker Filament → Filament entladen wählen. Filament und Spule entfernen. Vorheizen → Abkühlen wählen und warten, bis Düse und Bett Raumtemperatur erreicht haben."]},{"id":409245,"title":["ベッドを下げ、電源を切って抜く","Lower the bed and disconnect power","Spuštění podložky a odpojení napájení","Bett absenken und Netzverbindung trennen"],"body":["実機の「コントロール → ジクノ イドウ → Zジクノ ソウサ」を100 mm以上に設定し、ベッドが下がり終わるまで待ちます。その後、背面のスイッチを切り、電源コードを抜いてください。","On the printer, set Control → Move Axis → Move Z to at least 100 mm and wait for the bed to stop moving. Then switch off at the rear and unplug the power cable.","V nabídce Ovládání → Pohyb osy → Osa Z nastavte alespoň 100 mm a počkejte na dokončení pohybu podložky. Poté vypněte zadní vypínač a odpojte napájecí kabel.","Am Drucker Steuerung → Achsen Bewegen → Bewege Z auf mindestens 100 mm einstellen und das Ende der Bettbewegung abwarten. Danach hinten ausschalten und das Netzkabel ziehen."]},{"id":411192,"title":["右のハンドルを外す","Remove the right handle","Demontáž pravé rukojeti","Rechten Griff abnehmen"],"body":["右側から作業し、T10でハンドルのねじ2本を1本ずつ外します。PTFEチューブの後ろに隠れたねじは、チューブを軽くよけて取り出してください。強く曲げず、ハンドルをチューブから抜いて保管します。ねじの長さも記録し、別の型のねじと混ぜないでください。 短い入力PTFEが付いている場合は、コレットを押したまま真っすぐ抜き、切らずに保管します。","Work from the right and remove the two handle screws individually with T10. Gently move the PTFE tube aside to reach the hidden screw without sharply bending it. Slide the handle off the tube and keep it with its screws. Record their length rather than mixing hardware from another housing version. If a short input PTFE tube is fitted, hold its collet in, pull the tube straight out and keep its full length.","Z pravé strany vyšroubujte klíčem T10 oba šrouby rukojeti, každý zvlášť. Ke skrytému šroubu se dostaňte mírným odkloněním PTFE trubičky, bez ostrého ohnutí. Rukojeť stáhněte z trubičky a uložte se šrouby. Zaznamenejte jejich délku a nemíchejte je s upevněním jiné verze. Je-li osazena krátká vstupní PTFE trubička, podržte její kleštinu, trubičku vytáhněte přímo a ponechte ji nezkrácenou.","Von rechts beide Griffschrauben einzeln mit T10 herausdrehen. Den PTFE-Schlauch vorsichtig zur Seite bewegen, um die verdeckte Schraube zu erreichen; nicht scharf knicken. Griff vom Schlauch abziehen und mit seinen Schrauben ablegen. Schraubenlänge festhalten und die Gehäusevarianten nicht vermischen. Bei vorhandenem kurzem Eingangs-PTFE den Klemmring drücken, Schlauch gerade herausziehen und ungekürzt aufbewahren."]},{"id":411237,"title":["11本のリベットと右パネルを外す","Remove eleven rivets and the right panel","Vyjmutí jedenácti nýtů a pravého panelu","Elf Niete und rechtes Blech abnehmen"],"body":["パネルを支えながら、ナイロンリベット11本を外します。中央の頭を少し持ち上げてロックを解き、外側の筒を抜きます。ニッパーで切らないでください。パネルをゆっくりよけ、PTFEと配線でつながっているセンサーユニットを手で支えます。配線に重さを掛けたり、引っ張ったりしないでください。 長いPTFEのコレットを押してチューブを真っすぐ抜きます。チューブと配線を引っ張らず、センサー全体を手で支えて空いた場所へよけてください。","Support the panel and remove its eleven nylon rivets. Lift each centre pin enough to unlock it, then withdraw the outer sleeve without cutting it. Move the panel away slowly and support the sensor assembly, which remains attached to the PTFE tube and cable. Do not leave its weight on the cable or pull the wiring. Hold the long-tube collet in and withdraw the PTFE straight. Support the complete sensor in free working space without pulling on the tube or cable.","Podepřete panel a vyjměte jedenáct nylonových nýtů. Nadzvedněte středový kolík pro odjištění a potom vytáhněte vnější pouzdro; nýt nepřestřihujte. Panel pomalu odsuňte a podepřete senzor, který zůstává spojený s PTFE trubičkou a kabelem. Kabel nenapínejte ani na něj nezavěšujte hmotnost sestavy. Podržte kleštinu dlouhé trubičky a PTFE vytáhněte přímo. Celý senzor podepřete ve volném prostoru, bez tahu za trubičku nebo kabel.","Blech abstützen und die elf Nylon-Niete entfernen. Jeweils den Mittelstift zum Entriegeln anheben, dann die äußere Hülse herausziehen; nichts abschneiden. Blech langsam wegbewegen und die noch an PTFE-Schlauch und Kabel hängende Sensorbaugruppe mit der Hand tragen. Kabel weder belasten noch daran ziehen. Klemmring des langen Schlauchs drücken und PTFE gerade herausziehen. Gesamten Sensor im freien Arbeitsraum halten, ohne an Schlauch oder Kabel zu ziehen."]},{"id":411278,"title":["カバーを開き、旧IR基板を抜く","Open the cover and remove the old IR board","Otevření krytu a vyjmutí původní IR desky","Abdeckung öffnen und alte IR-Platine ausbauen"],"body":["本体を支え、選んだ型に合うカバーねじを2.5 mm六角レンチで外します。旧片側ねじ式は写真で示す右のM3x10だけを外し、残した側を無理に引き抜かないでください。両側ねじ式は2本を外します。次に1.5 mm六角レンチで基板のM2x8を外し、基板の縁を持って溝から横へ抜きます。基板を支えたままコネクターのハウジングを持って外し、配線を引っ張らないでください。","Support the housing and remove the cover screws for the selected version with a 2.5 mm hex key. On the early cover release only the right M3x10 shown in the photo; do not force the retained side apart. The later cover has two removable screws. Remove the board’s M2x8 with the 1.5 mm key. Hold the board by its edges, move it sideways out of the groove, then unplug the connector by its housing while supporting the board. Do not pull the wires.","Podepřete pouzdro a imbusem 2,5 mm vyjměte šrouby krytu odpovídající zvolené verzi. U staršího krytu uvolněte jen pravý M3x10 na fotografii a nepáčte ponechanou stranu. Novější kryt má dva vyjímané šrouby. Imbusem 1,5 mm vyjměte M2x8 desky. Desku držte za okraje, vysuňte bokem z drážky a podepřenou ji odpojte za těleso konektoru. Netahejte za vodiče.","Gehäuse halten und die zur gewählten Version gehörenden Deckelschrauben mit 2,5 mm Innensechskant lösen. Bei der frühen Abdeckung nur den rechts gezeigten M3x10 entfernen und die verbleibende Seite nicht auseinanderzwingen. Die spätere Abdeckung hat zwei herausnehmbare Schrauben. M2x8 der Platine mit 1,5 mm lösen. Platine an den Kanten halten, seitlich aus der Nut führen und den Stecker am Gehäuse abziehen. Nicht an Leitungen ziehen."]},{"id":411322,"title":["交換用IR基板を確認する","Check the replacement IR board","Kontrola náhradní IR desky","Ersatz-IR-Platine prüfen"],"body":["旧基板を保管し、交換用IRフィラメントセンサーを1枚用意します。光学ゲートと端子表示を見比べ、Nextruder用の磁気式基板と取り違えないでください。電子部品に触れず、基板の縁を持って扱います。","Keep the removed board aside and prepare one replacement IR filament-sensor board. Compare its optical gate and terminal markings; do not substitute the magnetic sensor used inside the Nextruder. Handle the board by its edges without touching electronic components.","Původní desku odložte a připravte jednu náhradní IR desku. Porovnejte optickou bránu a označení vývodů; nezaměňte ji za magnetický senzor uvnitř Nextruderu. Desku držte za okraje a nedotýkejte se elektronických součástek.","Alte Platine ablegen und eine Ersatz-IR-Platine bereitlegen. Lichtschranke und Anschlussmarkierungen vergleichen; nicht mit dem Magnetsensor im Nextruder verwechseln. Nur an den Platinenkanten anfassen, ohne elektronische Bauteile zu berühren."]},{"id":411472,"title":["極性を合わせて接続し、溝へ入れる","Connect with correct polarity and seat in the groove","Zapojení se správnou polaritou a zasunutí do drážky","Polrichtig anschließen und in die Nut einsetzen"],"body":["基板上の表示を見て、茶色の線を+5V、白い線をGNDに合わせます。一般的な線色の思い込みで逆向きにしないでください。コネクターをまっすぐ差したら、先に配線を本体の溝へ入れ、次にIR基板を専用の溝へ収めます。配線とコネクターをレバーの動く範囲から外してください。","Use the board markings: brown goes to +5V and white to GND. Do not reverse the plug based on usual wire-colour conventions. Insert it straight, place the cable in the housing groove first, then seat the IR board in its own groove. Keep the connector and wires out of the lever’s moving space.","Řiďte se popisem desky: hnědý vodič patří na +5V a bílý na GND. Nespoléhejte na běžné barevné značení. Konektor zasuňte rovně, nejprve vložte kabel do drážky pouzdra a poté desku do její drážky. Konektor i vodiče musí zůstat mimo pohyb páčky.","Auf den Platinenaufdruck achten: Braun gehört an +5V, Weiß an GND. Nicht nach üblichen Kabelfarben umgekehrt anschließen. Stecker gerade einführen, zuerst das Kabel in die Gehäusenut legen und dann die IR-Platine in ihre Nut einsetzen. Stecker und Leitungen aus dem Bewegungsbereich des Hebels halten."]},{"id":411569,"title":["レバーを確認し、基板とカバーを固定する","Check the lever and secure board and cover","Kontrola páčky a upevnění desky a krytu","Hebel prüfen und Platine sowie Abdeckung befestigen"],"body":["レバーが光学ゲートへ正しく入り、軽く動くことを確認します。カバーを元の位置へ戻し、外したM3x10で留めてから、M2x8を1.5 mm六角レンチでやさしく締めます。片側を残す型は残した側を無理に引き抜かず、ねじ2本の型は両側を戻します。中央のレバー固定ねじは増し締めしません。","Check that the lever enters the optical gate and moves freely. Refit the cover with the removed M3x10 hardware, then gently tighten M2x8 with the1.5 mm key. Keep the retained side of a one-side cover in place; restore both sides on a two-screw cover. Do not tighten the central lever pivot screw.","Ověřte volný pohyb páčky v optické bráně. Vraťte kryt a původní M3x10, poté jemně dotáhněte M2x8 imbusem1,5 mm. U jednostranného krytu ponechanou stranu nevypáčte, u dvoušroubového vraťte oba šrouby. Středový šroub páčky nedotahujte.","Freien Hebelweg in der Lichtschranke prüfen. Abdeckung mit den ausgebauten M3x10 befestigen und danach M2x8 vorsichtig mit1,5 mm anziehen. Die verbleibende Seite einer einseitig gelösten Abdeckung nicht herauszwingen; bei zwei Schrauben beide montieren. Mittlere Hebelachsschraube nicht nachziehen."]},{"id":1260935,"title":["パネルとセンサーを元の取付けに合わせる","Match panel and sensor to their mounting version","Slícování panelu a senzoru podle verze","Blech und Sensor passend zur Version ausrichten"],"body":["センサーを元の位置に戻し、長いPTFEをコレットの奥まで差します。軽く引いて抜けないことを確かめてください。 センサーを手で支え、PTFEを右パネルの穴へ通しながらパネルを元の位置に合わせます。配線がフレームとパネルの間に挟まっていないことを確かめ、ナイロンリベット11本の筒と中央ピンを1本ずつ戻して固定してください。","Return the sensor to its mounting position and insert the long PTFE fully into the collet. Pull gently to check that it is retained. Support the sensor by hand and pass the PTFE tube through the panel opening as the right panel returns to position. Check that no cable is trapped against the frame, then refit all eleven nylon-rivet sleeves and centre pins individually.","Vraťte senzor do montážní polohy a dlouhé PTFE zasuňte do kleštiny až na doraz. Lehkým tahem ověřte zajištění. Podepřete senzor rukou a při vracení pravého panelu protáhněte PTFE jeho otvorem. Zkontrolujte, že kabel není sevřený rámem, a jednotlivě vraťte všech jedenáct pouzder nýtů i středových kolíků.","Sensor in die Einbaulage zurückführen und langen PTFE bis zum Anschlag in die Klemmhülse stecken. Durch leichtes Ziehen den Halt prüfen. Sensor von Hand halten und PTFE beim Ansetzen des rechten Blechs durch dessen Öffnung führen. Auf nicht eingeklemmte Kabel achten und alle elf Niethülsen und Mittelstifte einzeln einsetzen."]},{"id":1261005,"title":["右側を固定し、チューブを戻す","Secure the right side and refit the tube","Upevnění pravé strany a vrácení trubičky","Rechte Seite befestigen und Schlauch einsetzen"],"body":["センサーを内側から支えながらハンドルをPTFEへ通し、外したものと同じ長さのT10ねじ2本で固定します。短い入力PTFEを外していた場合は、4×2.5×45 mmのチューブをコレットへ奥まで戻してください。突き出した部分は切りません。","Support the sensor from inside, slide the handle over the PTFE and fasten its two T10 screws in the removed length. If the short input tube was removed, push the4×2.5×45 mm tube fully into its collet. Do not trim its protruding end.","Senzor podepřete zevnitř, rukojeť nasuňte na PTFE a upevněte dvěma šrouby T10 původní délky. Byla-li krátká vstupní trubička vyjmuta, zasuňte4×2,5×45 mm PTFE až na doraz do kleštiny. Vyčnívající konec nekracujte.","Sensor von innen halten, Griff über den PTFE schieben und mit zwei T10-Schrauben der ausgebauten Länge befestigen. Einen entfernten kurzen Eingangsschlauch4×2,5×45 mm vollständig in die Klemmhülse stecken. Überstand nicht kürzen."]},{"id":830914,"title":["実機でセンサー情報を開く","Open Sensor Info on the printer","Otevření údajů senzoru na tiskárně","Sensorinformationen am Drucker öffnen"],"body":["パネルと配線の固定を確認してから電源コードを接続し、背面スイッチを入れてドアを閉めます。実機の「ジョウホウ → センサージョウホウ」で側面センサーの項目を表示してください。One+は機械式スイッチがONであることも確認します。","After checking that the panel and wiring are secure, reconnect power, switch on at the rear and close the door. Open Info → Sensor Info on the printer and find Side Filament Sensor. On One+, also check that its mechanical switch is ON.","Po kontrole upevnění panelu a kabeláže připojte napájení, zapněte zadní vypínač a zavřete dveře. Na tiskárně otevřete Info → Stav senzoru a položku bočního senzoru filamentu. U One+ ověřte také polohu ON mechanického přepínače.","Nach Kontrolle von Blech und Verkabelung Netzkabel anschließen, hinten einschalten und die Tür schließen. Am Drucker Info → Sensor Info öffnen und den seitlichen Filamentsensor suchen. Bei One+ zusätzlich die ON-Stellung des mechanischen Schalters prüfen."]},{"id":830955,"title":["フィラメントの有無で表示が変わるか試す","Test the reading with and without filament","Zkouška údaje bez filamentu a s filamentem","Anzeige ohne und mit Filament prüfen"],"body":["フィラメントがないときはNINS／1を確認します。入力PTFEからセンサーを通るところまでフィラメントを入れ、INS／2へ変わることを確認してください。NINSは未挿入、INSは挿入です。変化しない場合は作業完了にせず、電源を切って冷却・抜栓してから極性、配線の挟み込み、レバーと光学ゲートの位置を見直します。","With no filament, check for NINS／1. Feed filament through the input PTFE far enough to pass the side sensor and confirm a change to INS／2. NINS means not inserted; INS means inserted. If it does not change, do not mark the repair complete. Switch off, cool and unplug before checking polarity, trapped wiring and lever alignment in the optical gate.","Bez filamentu ověřte NINS／1. Zasuňte filament vstupním PTFE tak daleko, aby prošel bočním senzorem, a ověřte změnu na INS／2. NINS znamená nevložený, INS vložený. Pokud se údaj nemění, opravu neoznačujte za dokončenou. Před kontrolou polarity, sevřených vodičů a páčky v optické bráně tiskárnu vypněte, nechte vychladnout a odpojte.","Ohne Filament NINS／1 prüfen. Filament durch den Eingangs-PTFE bis durch den Seitensensor einführen und den Wechsel auf INS／2 bestätigen. NINS heißt nicht eingeführt, INS eingeführt. Ohne Zustandswechsel die Reparatur nicht abschließen. Vor Prüfung von Polung, eingeklemmten Leitungen und Hebelposition in der Lichtschranke ausschalten, abkühlen lassen und Netzstecker ziehen."]},{"id":830995,"title":["固定と検出を確認して完了する","Finish after securing and testing","Dokončení po kontrole upevnění a funkce","Nach Befestigungs- und Funktionsprüfung abschließen"],"body":["ねじとリベットの戻し忘れ、配線の挟み込み、PTFEの折れがないか確認します。フィラメントの有無でセンサー表示が切り替わり、レバーが戻ることを確かめてから、スプールを戻して通常のロードへ進んでください。","Check for missing screws or rivets, trapped wires and kinked PTFE. Confirm that the sensor reading changes with filament and that the lever returns, then refit the spool and proceed with normal loading.","Zkontrolujte chybějící šrouby a nýty, sevřené vodiče a zalomené PTFE. Ověřte změnu údaje při vložení filamentu i návrat páčky. Poté vraťte cívku a pokračujte běžným zavedením filamentu.","Auf fehlende Schrauben oder Niete, eingeklemmte Kabel und geknickten PTFE achten. Zustandswechsel bei Filament sowie Rückkehr des Hebels prüfen. Danach Spule einsetzen und mit dem normalen Laden fortfahren."]}],"r1-two":[{"id":408991,"title":["側面IRセンサーと本体の型を確認する","Identify the side IR sensor and housing","Určení bočního IR senzoru a pouzdra","Seitlichen IR-Sensor und Gehäuse bestimmen"],"body":["側面のIR基板を交換します。Nextruder内のセンサーとは別の部品です。交換用IR基板を用意し、実物のカバーとねじ位置を写真で確認してください。旧型の片側ねじ式、両側ねじ式、スイッチ付きOne+では、カバーと取付けねじが異なります。","Replace the IR board in the side sensor, which is separate from the sensor inside the Nextruder. Have the replacement board ready and compare the actual cover and screw locations with the photos. The early single-side cover, later two-screw cover and switched One+ housing use different cover and mounting hardware.","Vyměňuje se IR deska bočního senzoru, nikoli senzor uvnitř Nextruderu. Připravte náhradní desku a porovnejte skutečný kryt a polohy šroubů s fotografiemi. Starší kryt s jedním uvolňovaným šroubem, novější kryt se dvěma šrouby a pouzdro One+ s přepínačem mají odlišné upevnění.","Ersetzt wird die IR-Platine des seitlichen Sensors, nicht der Sensor im Nextruder. Ersatzplatine bereitlegen und Abdeckung sowie Schraubenpositionen am Drucker mit den Fotos vergleichen. Frühe einseitig gelöste Abdeckung, spätere Abdeckung mit zwei Schrauben und One+ mit Schalter haben unterschiedliche Befestigungen."]},{"id":409081,"title":["工具と交換基板を用意する","Prepare tools and the replacement board","Příprava nářadí a náhradní desky","Werkzeuge und Ersatzplatine bereitlegen"],"body":["2.5 mmと1.5 mmの六角レンチ、T10 Torxを用意します。ナイロンリベットの頭を持ち上げるには薄刃ニッパーがあると便利です。リベットを切断するためには使いません。外したねじを種類ごとに保管できる場所も用意してください。","Prepare 2.5 mm and 1.5 mm hex keys and a T10 Torx key. Flush cutters can help lift the nylon rivet heads; use them to lift, not cut. Set aside a place to keep the different removed screws separate.","Připravte imbusy 2,5 a 1,5 mm a klíč Torx T10. Štípací kleště mohou pomoci nadzvednout hlavy nylonových nýtů; nýty s nimi nestříhejte. Připravte místo pro oddělené uložení různých vyjmutých šroubů.","Innensechskantschlüssel 2,5 und 1,5 mm sowie Torx T10 bereitlegen. Ein Seitenschneider hilft beim Anheben der Nylon-Nietköpfe; die Niete damit nicht durchtrennen. Unterschiedliche ausgebaute Schrauben getrennt ablegen."]},{"id":409117,"title":["フィラメントを抜き、十分に冷ます","Unload filament and let the printer cool","Vysunutí filamentu a vychladnutí tiskárny","Filament entladen und Drucker abkühlen lassen"],"body":["ドアを閉め、実機の「フィラメント → フィラメント アンロード」でフィラメントを抜きます。スプールも外してください。「プレヒート → クールダウン」を選び、ノズルとベッドが室温まで下がるのを待ちます。","Close the door and use Filament → Unload Filament on the printer. Remove the filament and spool. Select Preheat → COOLDOWN and wait until the nozzle and bed have cooled to room temperature.","Zavřete dveře a na tiskárně zvolte Filament → Vyjmout filament. Vyjměte filament i cívku. Zvolte Předehřev → Zchladit a počkejte, až tryska i podložka vychladnou na pokojovou teplotu.","Tür schließen und am Drucker Filament → Filament entladen wählen. Filament und Spule entfernen. Vorheizen → Abkühlen wählen und warten, bis Düse und Bett Raumtemperatur erreicht haben."]},{"id":409245,"title":["ベッドを下げ、電源を切って抜く","Lower the bed and disconnect power","Spuštění podložky a odpojení napájení","Bett absenken und Netzverbindung trennen"],"body":["実機の「コントロール → ジクノ イドウ → Zジクノ ソウサ」を100 mm以上に設定し、ベッドが下がり終わるまで待ちます。その後、背面のスイッチを切り、電源コードを抜いてください。","On the printer, set Control → Move Axis → Move Z to at least 100 mm and wait for the bed to stop moving. Then switch off at the rear and unplug the power cable.","V nabídce Ovládání → Pohyb osy → Osa Z nastavte alespoň 100 mm a počkejte na dokončení pohybu podložky. Poté vypněte zadní vypínač a odpojte napájecí kabel.","Am Drucker Steuerung → Achsen Bewegen → Bewege Z auf mindestens 100 mm einstellen und das Ende der Bettbewegung abwarten. Danach hinten ausschalten und das Netzkabel ziehen."]},{"id":411192,"title":["右のハンドルを外す","Remove the right handle","Demontáž pravé rukojeti","Rechten Griff abnehmen"],"body":["右側から作業し、T10でハンドルのねじ2本を1本ずつ外します。PTFEチューブの後ろに隠れたねじは、チューブを軽くよけて取り出してください。強く曲げず、ハンドルをチューブから抜いて保管します。ねじの長さも記録し、別の型のねじと混ぜないでください。 短い入力PTFEが付いている場合は、コレットを押したまま真っすぐ抜き、切らずに保管します。","Work from the right and remove the two handle screws individually with T10. Gently move the PTFE tube aside to reach the hidden screw without sharply bending it. Slide the handle off the tube and keep it with its screws. Record their length rather than mixing hardware from another housing version. If a short input PTFE tube is fitted, hold its collet in, pull the tube straight out and keep its full length.","Z pravé strany vyšroubujte klíčem T10 oba šrouby rukojeti, každý zvlášť. Ke skrytému šroubu se dostaňte mírným odkloněním PTFE trubičky, bez ostrého ohnutí. Rukojeť stáhněte z trubičky a uložte se šrouby. Zaznamenejte jejich délku a nemíchejte je s upevněním jiné verze. Je-li osazena krátká vstupní PTFE trubička, podržte její kleštinu, trubičku vytáhněte přímo a ponechte ji nezkrácenou.","Von rechts beide Griffschrauben einzeln mit T10 herausdrehen. Den PTFE-Schlauch vorsichtig zur Seite bewegen, um die verdeckte Schraube zu erreichen; nicht scharf knicken. Griff vom Schlauch abziehen und mit seinen Schrauben ablegen. Schraubenlänge festhalten und die Gehäusevarianten nicht vermischen. Bei vorhandenem kurzem Eingangs-PTFE den Klemmring drücken, Schlauch gerade herausziehen und ungekürzt aufbewahren."]},{"id":411237,"title":["11本のリベットと右パネルを外す","Remove eleven rivets and the right panel","Vyjmutí jedenácti nýtů a pravého panelu","Elf Niete und rechtes Blech abnehmen"],"body":["パネルを支えながら、ナイロンリベット11本を外します。中央の頭を少し持ち上げてロックを解き、外側の筒を抜きます。ニッパーで切らないでください。パネルをゆっくりよけ、PTFEと配線でつながっているセンサーユニットを手で支えます。配線に重さを掛けたり、引っ張ったりしないでください。 長いPTFEのコレットを押してチューブを真っすぐ抜きます。チューブと配線を引っ張らず、センサー全体を手で支えて空いた場所へよけてください。","Support the panel and remove its eleven nylon rivets. Lift each centre pin enough to unlock it, then withdraw the outer sleeve without cutting it. Move the panel away slowly and support the sensor assembly, which remains attached to the PTFE tube and cable. Do not leave its weight on the cable or pull the wiring. Hold the long-tube collet in and withdraw the PTFE straight. Support the complete sensor in free working space without pulling on the tube or cable.","Podepřete panel a vyjměte jedenáct nylonových nýtů. Nadzvedněte středový kolík pro odjištění a potom vytáhněte vnější pouzdro; nýt nepřestřihujte. Panel pomalu odsuňte a podepřete senzor, který zůstává spojený s PTFE trubičkou a kabelem. Kabel nenapínejte ani na něj nezavěšujte hmotnost sestavy. Podržte kleštinu dlouhé trubičky a PTFE vytáhněte přímo. Celý senzor podepřete ve volném prostoru, bez tahu za trubičku nebo kabel.","Blech abstützen und die elf Nylon-Niete entfernen. Jeweils den Mittelstift zum Entriegeln anheben, dann die äußere Hülse herausziehen; nichts abschneiden. Blech langsam wegbewegen und die noch an PTFE-Schlauch und Kabel hängende Sensorbaugruppe mit der Hand tragen. Kabel weder belasten noch daran ziehen. Klemmring des langen Schlauchs drücken und PTFE gerade herausziehen. Gesamten Sensor im freien Arbeitsraum halten, ohne an Schlauch oder Kabel zu ziehen."]},{"id":411278,"title":["カバーを開き、旧IR基板を抜く","Open the cover and remove the old IR board","Otevření krytu a vyjmutí původní IR desky","Abdeckung öffnen und alte IR-Platine ausbauen"],"body":["本体を支え、選んだ型に合うカバーねじを2.5 mm六角レンチで外します。旧片側ねじ式は写真で示す右のM3x10だけを外し、残した側を無理に引き抜かないでください。両側ねじ式は2本を外します。次に1.5 mm六角レンチで基板のM2x8を外し、基板の縁を持って溝から横へ抜きます。基板を支えたままコネクターのハウジングを持って外し、配線を引っ張らないでください。","Support the housing and remove the cover screws for the selected version with a 2.5 mm hex key. On the early cover release only the right M3x10 shown in the photo; do not force the retained side apart. The later cover has two removable screws. Remove the board’s M2x8 with the 1.5 mm key. Hold the board by its edges, move it sideways out of the groove, then unplug the connector by its housing while supporting the board. Do not pull the wires.","Podepřete pouzdro a imbusem 2,5 mm vyjměte šrouby krytu odpovídající zvolené verzi. U staršího krytu uvolněte jen pravý M3x10 na fotografii a nepáčte ponechanou stranu. Novější kryt má dva vyjímané šrouby. Imbusem 1,5 mm vyjměte M2x8 desky. Desku držte za okraje, vysuňte bokem z drážky a podepřenou ji odpojte za těleso konektoru. Netahejte za vodiče.","Gehäuse halten und die zur gewählten Version gehörenden Deckelschrauben mit 2,5 mm Innensechskant lösen. Bei der frühen Abdeckung nur den rechts gezeigten M3x10 entfernen und die verbleibende Seite nicht auseinanderzwingen. Die spätere Abdeckung hat zwei herausnehmbare Schrauben. M2x8 der Platine mit 1,5 mm lösen. Platine an den Kanten halten, seitlich aus der Nut führen und den Stecker am Gehäuse abziehen. Nicht an Leitungen ziehen."]},{"id":411322,"title":["交換用IR基板を確認する","Check the replacement IR board","Kontrola náhradní IR desky","Ersatz-IR-Platine prüfen"],"body":["旧基板を保管し、交換用IRフィラメントセンサーを1枚用意します。光学ゲートと端子表示を見比べ、Nextruder用の磁気式基板と取り違えないでください。電子部品に触れず、基板の縁を持って扱います。","Keep the removed board aside and prepare one replacement IR filament-sensor board. Compare its optical gate and terminal markings; do not substitute the magnetic sensor used inside the Nextruder. Handle the board by its edges without touching electronic components.","Původní desku odložte a připravte jednu náhradní IR desku. Porovnejte optickou bránu a označení vývodů; nezaměňte ji za magnetický senzor uvnitř Nextruderu. Desku držte za okraje a nedotýkejte se elektronických součástek.","Alte Platine ablegen und eine Ersatz-IR-Platine bereitlegen. Lichtschranke und Anschlussmarkierungen vergleichen; nicht mit dem Magnetsensor im Nextruder verwechseln. Nur an den Platinenkanten anfassen, ohne elektronische Bauteile zu berühren."]},{"id":411472,"title":["極性を合わせて接続し、溝へ入れる","Connect with correct polarity and seat in the groove","Zapojení se správnou polaritou a zasunutí do drážky","Polrichtig anschließen und in die Nut einsetzen"],"body":["基板上の表示を見て、茶色の線を+5V、白い線をGNDに合わせます。一般的な線色の思い込みで逆向きにしないでください。コネクターをまっすぐ差したら、先に配線を本体の溝へ入れ、次にIR基板を専用の溝へ収めます。配線とコネクターをレバーの動く範囲から外してください。","Use the board markings: brown goes to +5V and white to GND. Do not reverse the plug based on usual wire-colour conventions. Insert it straight, place the cable in the housing groove first, then seat the IR board in its own groove. Keep the connector and wires out of the lever’s moving space.","Řiďte se popisem desky: hnědý vodič patří na +5V a bílý na GND. Nespoléhejte na běžné barevné značení. Konektor zasuňte rovně, nejprve vložte kabel do drážky pouzdra a poté desku do její drážky. Konektor i vodiče musí zůstat mimo pohyb páčky.","Auf den Platinenaufdruck achten: Braun gehört an +5V, Weiß an GND. Nicht nach üblichen Kabelfarben umgekehrt anschließen. Stecker gerade einführen, zuerst das Kabel in die Gehäusenut legen und dann die IR-Platine in ihre Nut einsetzen. Stecker und Leitungen aus dem Bewegungsbereich des Hebels halten."]},{"id":411569,"title":["レバーを確認し、基板とカバーを固定する","Check the lever and secure board and cover","Kontrola páčky a upevnění desky a krytu","Hebel prüfen und Platine sowie Abdeckung befestigen"],"body":["レバーが光学ゲートへ正しく入り、軽く動くことを確認します。カバーを元の位置へ戻し、外したM3x10で留めてから、M2x8を1.5 mm六角レンチでやさしく締めます。片側を残す型は残した側を無理に引き抜かず、ねじ2本の型は両側を戻します。中央のレバー固定ねじは増し締めしません。","Check that the lever enters the optical gate and moves freely. Refit the cover with the removed M3x10 hardware, then gently tighten M2x8 with the1.5 mm key. Keep the retained side of a one-side cover in place; restore both sides on a two-screw cover. Do not tighten the central lever pivot screw.","Ověřte volný pohyb páčky v optické bráně. Vraťte kryt a původní M3x10, poté jemně dotáhněte M2x8 imbusem1,5 mm. U jednostranného krytu ponechanou stranu nevypáčte, u dvoušroubového vraťte oba šrouby. Středový šroub páčky nedotahujte.","Freien Hebelweg in der Lichtschranke prüfen. Abdeckung mit den ausgebauten M3x10 befestigen und danach M2x8 vorsichtig mit1,5 mm anziehen. Die verbleibende Seite einer einseitig gelösten Abdeckung nicht herauszwingen; bei zwei Schrauben beide montieren. Mittlere Hebelachsschraube nicht nachziehen."]},{"id":1260935,"title":["パネルとセンサーを元の取付けに合わせる","Match panel and sensor to their mounting version","Slícování panelu a senzoru podle verze","Blech und Sensor passend zur Version ausrichten"],"body":["センサーを元の位置に戻し、長いPTFEをコレットの奥まで差します。軽く引いて抜けないことを確かめてください。 センサーを手で支え、PTFEを右パネルの穴へ通しながらパネルを元の位置に合わせます。配線がフレームとパネルの間に挟まっていないことを確かめ、ナイロンリベット11本の筒と中央ピンを1本ずつ戻して固定してください。","Return the sensor to its mounting position and insert the long PTFE fully into the collet. Pull gently to check that it is retained. Support the sensor by hand and pass the PTFE tube through the panel opening as the right panel returns to position. Check that no cable is trapped against the frame, then refit all eleven nylon-rivet sleeves and centre pins individually.","Vraťte senzor do montážní polohy a dlouhé PTFE zasuňte do kleštiny až na doraz. Lehkým tahem ověřte zajištění. Podepřete senzor rukou a při vracení pravého panelu protáhněte PTFE jeho otvorem. Zkontrolujte, že kabel není sevřený rámem, a jednotlivě vraťte všech jedenáct pouzder nýtů i středových kolíků.","Sensor in die Einbaulage zurückführen und langen PTFE bis zum Anschlag in die Klemmhülse stecken. Durch leichtes Ziehen den Halt prüfen. Sensor von Hand halten und PTFE beim Ansetzen des rechten Blechs durch dessen Öffnung führen. Auf nicht eingeklemmte Kabel achten und alle elf Niethülsen und Mittelstifte einzeln einsetzen."]},{"id":1261005,"title":["右側を固定し、チューブを戻す","Secure the right side and refit the tube","Upevnění pravé strany a vrácení trubičky","Rechte Seite befestigen und Schlauch einsetzen"],"body":["センサーを内側から支えながらハンドルをPTFEへ通し、外したものと同じ長さのT10ねじ2本で固定します。短い入力PTFEを外していた場合は、4×2.5×45 mmのチューブをコレットへ奥まで戻してください。突き出した部分は切りません。","Support the sensor from inside, slide the handle over the PTFE and fasten its two T10 screws in the removed length. If the short input tube was removed, push the4×2.5×45 mm tube fully into its collet. Do not trim its protruding end.","Senzor podepřete zevnitř, rukojeť nasuňte na PTFE a upevněte dvěma šrouby T10 původní délky. Byla-li krátká vstupní trubička vyjmuta, zasuňte4×2,5×45 mm PTFE až na doraz do kleštiny. Vyčnívající konec nekracujte.","Sensor von innen halten, Griff über den PTFE schieben und mit zwei T10-Schrauben der ausgebauten Länge befestigen. Einen entfernten kurzen Eingangsschlauch4×2,5×45 mm vollständig in die Klemmhülse stecken. Überstand nicht kürzen."]},{"id":830914,"title":["実機でセンサー情報を開く","Open Sensor Info on the printer","Otevření údajů senzoru na tiskárně","Sensorinformationen am Drucker öffnen"],"body":["パネルと配線の固定を確認してから電源コードを接続し、背面スイッチを入れてドアを閉めます。実機の「ジョウホウ → センサージョウホウ」で側面センサーの項目を表示してください。One+は機械式スイッチがONであることも確認します。","After checking that the panel and wiring are secure, reconnect power, switch on at the rear and close the door. Open Info → Sensor Info on the printer and find Side Filament Sensor. On One+, also check that its mechanical switch is ON.","Po kontrole upevnění panelu a kabeláže připojte napájení, zapněte zadní vypínač a zavřete dveře. Na tiskárně otevřete Info → Stav senzoru a položku bočního senzoru filamentu. U One+ ověřte také polohu ON mechanického přepínače.","Nach Kontrolle von Blech und Verkabelung Netzkabel anschließen, hinten einschalten und die Tür schließen. Am Drucker Info → Sensor Info öffnen und den seitlichen Filamentsensor suchen. Bei One+ zusätzlich die ON-Stellung des mechanischen Schalters prüfen."]},{"id":830955,"title":["フィラメントの有無で表示が変わるか試す","Test the reading with and without filament","Zkouška údaje bez filamentu a s filamentem","Anzeige ohne und mit Filament prüfen"],"body":["フィラメントがないときはNINS／1を確認します。入力PTFEからセンサーを通るところまでフィラメントを入れ、INS／2へ変わることを確認してください。NINSは未挿入、INSは挿入です。変化しない場合は作業完了にせず、電源を切って冷却・抜栓してから極性、配線の挟み込み、レバーと光学ゲートの位置を見直します。","With no filament, check for NINS／1. Feed filament through the input PTFE far enough to pass the side sensor and confirm a change to INS／2. NINS means not inserted; INS means inserted. If it does not change, do not mark the repair complete. Switch off, cool and unplug before checking polarity, trapped wiring and lever alignment in the optical gate.","Bez filamentu ověřte NINS／1. Zasuňte filament vstupním PTFE tak daleko, aby prošel bočním senzorem, a ověřte změnu na INS／2. NINS znamená nevložený, INS vložený. Pokud se údaj nemění, opravu neoznačujte za dokončenou. Před kontrolou polarity, sevřených vodičů a páčky v optické bráně tiskárnu vypněte, nechte vychladnout a odpojte.","Ohne Filament NINS／1 prüfen. Filament durch den Eingangs-PTFE bis durch den Seitensensor einführen und den Wechsel auf INS／2 bestätigen. NINS heißt nicht eingeführt, INS eingeführt. Ohne Zustandswechsel die Reparatur nicht abschließen. Vor Prüfung von Polung, eingeklemmten Leitungen und Hebelposition in der Lichtschranke ausschalten, abkühlen lassen und Netzstecker ziehen."]},{"id":830995,"title":["固定と検出を確認して完了する","Finish after securing and testing","Dokončení po kontrole upevnění a funkce","Nach Befestigungs- und Funktionsprüfung abschließen"],"body":["ねじとリベットの戻し忘れ、配線の挟み込み、PTFEの折れがないか確認します。フィラメントの有無でセンサー表示が切り替わり、レバーが戻ることを確かめてから、スプールを戻して通常のロードへ進んでください。","Check for missing screws or rivets, trapped wires and kinked PTFE. Confirm that the sensor reading changes with filament and that the lever returns, then refit the spool and proceed with normal loading.","Zkontrolujte chybějící šrouby a nýty, sevřené vodiče a zalomené PTFE. Ověřte změnu údaje při vložení filamentu i návrat páčky. Poté vraťte cívku a pokračujte běžným zavedením filamentu.","Auf fehlende Schrauben oder Niete, eingeklemmte Kabel und geknickten PTFE achten. Zustandswechsel bei Filament sowie Rückkehr des Hebels prüfen. Danach Spule einsetzen und mit dem normalen Laden fortfahren."]}],"plus":[{"id":408991,"title":["側面IRセンサーと本体の型を確認する","Identify the side IR sensor and housing","Určení bočního IR senzoru a pouzdra","Seitlichen IR-Sensor und Gehäuse bestimmen"],"body":["側面のIR基板を交換します。Nextruder内のセンサーとは別の部品です。交換用IR基板を用意し、実物のカバーとねじ位置を写真で確認してください。旧型の片側ねじ式、両側ねじ式、スイッチ付きOne+では、カバーと取付けねじが異なります。","Replace the IR board in the side sensor, which is separate from the sensor inside the Nextruder. Have the replacement board ready and compare the actual cover and screw locations with the photos. The early single-side cover, later two-screw cover and switched One+ housing use different cover and mounting hardware.","Vyměňuje se IR deska bočního senzoru, nikoli senzor uvnitř Nextruderu. Připravte náhradní desku a porovnejte skutečný kryt a polohy šroubů s fotografiemi. Starší kryt s jedním uvolňovaným šroubem, novější kryt se dvěma šrouby a pouzdro One+ s přepínačem mají odlišné upevnění.","Ersetzt wird die IR-Platine des seitlichen Sensors, nicht der Sensor im Nextruder. Ersatzplatine bereitlegen und Abdeckung sowie Schraubenpositionen am Drucker mit den Fotos vergleichen. Frühe einseitig gelöste Abdeckung, spätere Abdeckung mit zwei Schrauben und One+ mit Schalter haben unterschiedliche Befestigungen."]},{"id":409081,"title":["工具と交換基板を用意する","Prepare tools and the replacement board","Příprava nářadí a náhradní desky","Werkzeuge und Ersatzplatine bereitlegen"],"body":["2.5 mmと1.5 mmの六角レンチ、T10 Torxを用意します。ナイロンリベットの頭を持ち上げるには薄刃ニッパーがあると便利です。リベットを切断するためには使いません。外したねじを種類ごとに保管できる場所も用意してください。","Prepare 2.5 mm and 1.5 mm hex keys and a T10 Torx key. Flush cutters can help lift the nylon rivet heads; use them to lift, not cut. Set aside a place to keep the different removed screws separate.","Připravte imbusy 2,5 a 1,5 mm a klíč Torx T10. Štípací kleště mohou pomoci nadzvednout hlavy nylonových nýtů; nýty s nimi nestříhejte. Připravte místo pro oddělené uložení různých vyjmutých šroubů.","Innensechskantschlüssel 2,5 und 1,5 mm sowie Torx T10 bereitlegen. Ein Seitenschneider hilft beim Anheben der Nylon-Nietköpfe; die Niete damit nicht durchtrennen. Unterschiedliche ausgebaute Schrauben getrennt ablegen."]},{"id":409117,"title":["フィラメントを抜き、十分に冷ます","Unload filament and let the printer cool","Vysunutí filamentu a vychladnutí tiskárny","Filament entladen und Drucker abkühlen lassen"],"body":["ドアを閉め、実機の「フィラメント → フィラメント アンロード」でフィラメントを抜きます。スプールも外してください。「プレヒート → クールダウン」を選び、ノズルとベッドが室温まで下がるのを待ちます。","Close the door and use Filament → Unload Filament on the printer. Remove the filament and spool. Select Preheat → COOLDOWN and wait until the nozzle and bed have cooled to room temperature.","Zavřete dveře a na tiskárně zvolte Filament → Vyjmout filament. Vyjměte filament i cívku. Zvolte Předehřev → Zchladit a počkejte, až tryska i podložka vychladnou na pokojovou teplotu.","Tür schließen und am Drucker Filament → Filament entladen wählen. Filament und Spule entfernen. Vorheizen → Abkühlen wählen und warten, bis Düse und Bett Raumtemperatur erreicht haben."]},{"id":409245,"title":["ベッドを下げ、電源を切って抜く","Lower the bed and disconnect power","Spuštění podložky a odpojení napájení","Bett absenken und Netzverbindung trennen"],"body":["実機の「コントロール → ジクノ イドウ → Zジクノ ソウサ」を100 mm以上に設定し、ベッドが下がり終わるまで待ちます。その後、背面のスイッチを切り、電源コードを抜いてください。","On the printer, set Control → Move Axis → Move Z to at least 100 mm and wait for the bed to stop moving. Then switch off at the rear and unplug the power cable.","V nabídce Ovládání → Pohyb osy → Osa Z nastavte alespoň 100 mm a počkejte na dokončení pohybu podložky. Poté vypněte zadní vypínač a odpojte napájecí kabel.","Am Drucker Steuerung → Achsen Bewegen → Bewege Z auf mindestens 100 mm einstellen und das Ende der Bettbewegung abwarten. Danach hinten ausschalten und das Netzkabel ziehen."]},{"id":411192,"title":["右のハンドルを外す","Remove the right handle","Demontáž pravé rukojeti","Rechten Griff abnehmen"],"body":["右側から作業し、T10でハンドルのねじ2本を1本ずつ外します。PTFEチューブの後ろに隠れたねじは、チューブを軽くよけて取り出してください。強く曲げず、ハンドルをチューブから抜いて保管します。ねじの長さも記録し、別の型のねじと混ぜないでください。 短い入力PTFEが付いている場合は、コレットを押したまま真っすぐ抜き、切らずに保管します。","Work from the right and remove the two handle screws individually with T10. Gently move the PTFE tube aside to reach the hidden screw without sharply bending it. Slide the handle off the tube and keep it with its screws. Record their length rather than mixing hardware from another housing version. If a short input PTFE tube is fitted, hold its collet in, pull the tube straight out and keep its full length.","Z pravé strany vyšroubujte klíčem T10 oba šrouby rukojeti, každý zvlášť. Ke skrytému šroubu se dostaňte mírným odkloněním PTFE trubičky, bez ostrého ohnutí. Rukojeť stáhněte z trubičky a uložte se šrouby. Zaznamenejte jejich délku a nemíchejte je s upevněním jiné verze. Je-li osazena krátká vstupní PTFE trubička, podržte její kleštinu, trubičku vytáhněte přímo a ponechte ji nezkrácenou.","Von rechts beide Griffschrauben einzeln mit T10 herausdrehen. Den PTFE-Schlauch vorsichtig zur Seite bewegen, um die verdeckte Schraube zu erreichen; nicht scharf knicken. Griff vom Schlauch abziehen und mit seinen Schrauben ablegen. Schraubenlänge festhalten und die Gehäusevarianten nicht vermischen. Bei vorhandenem kurzem Eingangs-PTFE den Klemmring drücken, Schlauch gerade herausziehen und ungekürzt aufbewahren."]},{"id":411237,"title":["11本のリベットと右パネルを外す","Remove eleven rivets and the right panel","Vyjmutí jedenácti nýtů a pravého panelu","Elf Niete und rechtes Blech abnehmen"],"body":["パネルを支えながら、ナイロンリベット11本を外します。中央の頭を少し持ち上げてロックを解き、外側の筒を抜きます。ニッパーで切らないでください。パネルをゆっくりよけ、PTFEと配線でつながっているセンサーユニットを手で支えます。配線に重さを掛けたり、引っ張ったりしないでください。 長いPTFEのコレットを押してチューブを真っすぐ抜きます。チューブと配線を引っ張らず、センサー全体を手で支えて空いた場所へよけてください。","Support the panel and remove its eleven nylon rivets. Lift each centre pin enough to unlock it, then withdraw the outer sleeve without cutting it. Move the panel away slowly and support the sensor assembly, which remains attached to the PTFE tube and cable. Do not leave its weight on the cable or pull the wiring. Hold the long-tube collet in and withdraw the PTFE straight. Support the complete sensor in free working space without pulling on the tube or cable.","Podepřete panel a vyjměte jedenáct nylonových nýtů. Nadzvedněte středový kolík pro odjištění a potom vytáhněte vnější pouzdro; nýt nepřestřihujte. Panel pomalu odsuňte a podepřete senzor, který zůstává spojený s PTFE trubičkou a kabelem. Kabel nenapínejte ani na něj nezavěšujte hmotnost sestavy. Podržte kleštinu dlouhé trubičky a PTFE vytáhněte přímo. Celý senzor podepřete ve volném prostoru, bez tahu za trubičku nebo kabel.","Blech abstützen und die elf Nylon-Niete entfernen. Jeweils den Mittelstift zum Entriegeln anheben, dann die äußere Hülse herausziehen; nichts abschneiden. Blech langsam wegbewegen und die noch an PTFE-Schlauch und Kabel hängende Sensorbaugruppe mit der Hand tragen. Kabel weder belasten noch daran ziehen. Klemmring des langen Schlauchs drücken und PTFE gerade herausziehen. Gesamten Sensor im freien Arbeitsraum halten, ohne an Schlauch oder Kabel zu ziehen."]},{"id":411278,"title":["カバーを開き、旧IR基板を抜く","Open the cover and remove the old IR board","Otevření krytu a vyjmutí původní IR desky","Abdeckung öffnen und alte IR-Platine ausbauen"],"body":["本体を手で支え、カバー両側のM3ねじを2.5 mm六角レンチで1本ずつ外してカバーをよけます。1.5 mm六角レンチでM2x8を抜き、基板の縁を持って溝から外してください。基板を支えたままコネクターのハウジングを持って抜き、配線を引っ張らないでください。","Support the housing and remove both cover M3 screws individually with the2.5 mm key. Lift the cover aside, remove the M2x8 with the1.5 mm key and hold the board by its edges as it leaves the groove. Unplug by the connector housing while supporting the board; do not pull the wires.","Podepřete pouzdro, imbusem2,5 mm jednotlivě vyjměte oba šrouby M3 krytu a kryt odložte. Imbusem1,5 mm vyjměte M2x8 a desku za okraje vysuňte z drážky. Podepřenou desku odpojte za těleso konektoru, nikoli tahem za vodiče.","Gehäuse halten, beide M3-Deckelschrauben einzeln mit2,5 mm lösen und die Abdeckung abheben. M2x8 mit1,5 mm entfernen und die Platine an den Kanten aus der Nut führen. Beim Abziehen am Steckergehäuse halten, nicht an Leitungen ziehen."]},{"id":411322,"title":["交換用IR基板を確認する","Check the replacement IR board","Kontrola náhradní IR desky","Ersatz-IR-Platine prüfen"],"body":["旧基板を保管し、交換用IRフィラメントセンサーを1枚用意します。光学ゲートと端子表示を見比べ、Nextruder用の磁気式基板と取り違えないでください。電子部品に触れず、基板の縁を持って扱います。","Keep the removed board aside and prepare one replacement IR filament-sensor board. Compare its optical gate and terminal markings; do not substitute the magnetic sensor used inside the Nextruder. Handle the board by its edges without touching electronic components.","Původní desku odložte a připravte jednu náhradní IR desku. Porovnejte optickou bránu a označení vývodů; nezaměňte ji za magnetický senzor uvnitř Nextruderu. Desku držte za okraje a nedotýkejte se elektronických součástek.","Alte Platine ablegen und eine Ersatz-IR-Platine bereitlegen. Lichtschranke und Anschlussmarkierungen vergleichen; nicht mit dem Magnetsensor im Nextruder verwechseln. Nur an den Platinenkanten anfassen, ohne elektronische Bauteile zu berühren."]},{"id":411472,"title":["極性を合わせて接続し、溝へ入れる","Connect with correct polarity and seat in the groove","Zapojení se správnou polaritou a zasunutí do drážky","Polrichtig anschließen und in die Nut einsetzen"],"body":["基板上の表示を見て、茶色の線を+5V、白い線をGNDに合わせます。一般的な線色の思い込みで逆向きにしないでください。コネクターをまっすぐ差したら、先に配線を本体の溝へ入れ、次にIR基板を専用の溝へ収めます。配線とコネクターをレバーの動く範囲から外してください。","Use the board markings: brown goes to +5V and white to GND. Do not reverse the plug based on usual wire-colour conventions. Insert it straight, place the cable in the housing groove first, then seat the IR board in its own groove. Keep the connector and wires out of the lever’s moving space.","Řiďte se popisem desky: hnědý vodič patří na +5V a bílý na GND. Nespoléhejte na běžné barevné značení. Konektor zasuňte rovně, nejprve vložte kabel do drážky pouzdra a poté desku do její drážky. Konektor i vodiče musí zůstat mimo pohyb páčky.","Auf den Platinenaufdruck achten: Braun gehört an +5V, Weiß an GND. Nicht nach üblichen Kabelfarben umgekehrt anschließen. Stecker gerade einführen, zuerst das Kabel in die Gehäusenut legen und dann die IR-Platine in ihre Nut einsetzen. Stecker und Leitungen aus dem Bewegungsbereich des Hebels halten."]},{"id":411569,"title":["レバーを確認し、基板とカバーを固定する","Check the lever and secure board and cover","Kontrola páčky a upevnění desky a krytu","Hebel prüfen und Platine sowie Abdeckung befestigen"],"body":["レバーが光学ゲートへ入り、配線やコネクターに当たらず軽く動くことを確認します。先にM2x8で基板をやさしく固定してください。スイッチも数回動かし、ONへ戻してからカバーをかぶせ、外したものと同じ長さのM3ねじ2本で留めます。中央のレバー固定ねじは増し締めしません。","Check that the lever enters the optical gate and moves freely without touching wires or connector. Gently secure the board with M2x8 first. Test the switch several times and leave it ON, then fit the cover with two M3 screws matching the removed length. Do not tighten the middle lever pivot screw.","Ověřte volný pohyb páčky v optické bráně bez dotyku s vodiči či konektorem. Nejprve jemně upevněte desku M2x8. Několikrát přepněte přepínač a ponechte ON. Nasaďte kryt a zajistěte dvěma šrouby M3 stejné délky jako původní. Středový šroub páčky nedotahujte.","Freien Hebelweg in der Lichtschranke ohne Kontakt mit Kabeln oder Stecker prüfen. Zuerst die Platine vorsichtig mit M2x8 befestigen. Schalter mehrmals betätigen und auf ON lassen. Dann die Abdeckung mit zwei M3 in der ausgebauten Länge montieren. Mittlere Hebelachsschraube nicht nachziehen."]},{"id":1260935,"title":["パネルとセンサーを元の取付けに合わせる","Match panel and sensor to their mounting version","Slícování panelu a senzoru podle verze","Blech und Sensor passend zur Version ausrichten"],"body":["センサーを元の位置に戻し、長いPTFEをコレットの奥まで差します。軽く引いて抜けないことを確かめてください。 右パネルとハンドルを本体へ近付け、PTFEの通り道とねじ穴を合わせます。後ろ側のハンドルねじをセンサーのナットへ軽く掛け、ナットが動く余裕を残したまま前の穴を合わせてください。センサーを配線で引き寄せないでください。","Return the sensor to its mounting position and insert the long PTFE fully into the collet. Pull gently to check that it is retained. Bring the right panel and handle close and align the PTFE passage and screw holes. Engage the rear handle screw loosely in the sensor nut, leaving it free to move while you align the front hole. Never pull the sensor into place by its cable.","Vraťte senzor do montážní polohy a dlouhé PTFE zasuňte do kleštiny až na doraz. Lehkým tahem ověřte zajištění. Přibližte pravý panel s rukojetí a srovnejte průchod PTFE a otvory šroubů. Zadní šroub rukojeti lehce nasaďte do matice senzoru a při vyrovnání předního otvoru nechte matici pohyblivou. Senzor nepřitahujte za kabel.","Sensor in die Einbaulage zurückführen und langen PTFE bis zum Anschlag in die Klemmhülse stecken. Durch leichtes Ziehen den Halt prüfen. Rechtes Blech und Griff nahe heranbringen und PTFE-Durchführung sowie Schraubenlöcher ausrichten. Hintere Griffschraube lose in die Sensormutter eindrehen, die Mutter beim Ausrichten des vorderen Lochs beweglich lassen. Sensor nicht am Kabel heranziehen."]},{"id":1261005,"title":["右側を固定し、チューブを戻す","Secure the right side and refit the tube","Upevnění pravé strany a vrácení trubičky","Rechte Seite befestigen und Schlauch einsetzen"],"body":["前のハンドルねじを入れて2本を固定し、パネルをナイロンリベット11本で留めます。配線をフレームとの間に挟まないでください。短い4×2.5×45 mmのPTFEをコレットへ奥まで入れ、突き出した部分は切らずに残します。","Fit the front handle screw and secure both screws, then refit all eleven panel rivets. Do not trap the sensor cable against the frame. Push the short4×2.5×45 mm PTFE tube fully into the collet and leave its protruding end uncut.","Vložte přední šroub rukojeti, upevněte oba šrouby a vraťte všech jedenáct nýtů panelu. Kabel nesmí být sevřený rámem. Krátkou4×2,5×45 mm PTFE trubičku zasuňte do kleštiny až na doraz a vyčnívající část ponechte nezkrácenou.","Vordere Griffschraube einsetzen, beide befestigen und alle elf Blechniete montieren. Sensorkabel nicht am Rahmen einklemmen. Kurzen PTFE-Schlauch4×2,5×45 mm vollständig in die Klemmhülse stecken und den Überstand nicht kürzen."]},{"id":830914,"title":["実機でセンサー情報を開く","Open Sensor Info on the printer","Otevření údajů senzoru na tiskárně","Sensorinformationen am Drucker öffnen"],"body":["パネルと配線の固定を確認してから電源コードを接続し、背面スイッチを入れてドアを閉めます。実機の「ジョウホウ → センサージョウホウ」で側面センサーの項目を表示してください。One+は機械式スイッチがONであることも確認します。","After checking that the panel and wiring are secure, reconnect power, switch on at the rear and close the door. Open Info → Sensor Info on the printer and find Side Filament Sensor. On One+, also check that its mechanical switch is ON.","Po kontrole upevnění panelu a kabeláže připojte napájení, zapněte zadní vypínač a zavřete dveře. Na tiskárně otevřete Info → Stav senzoru a položku bočního senzoru filamentu. U One+ ověřte také polohu ON mechanického přepínače.","Nach Kontrolle von Blech und Verkabelung Netzkabel anschließen, hinten einschalten und die Tür schließen. Am Drucker Info → Sensor Info öffnen und den seitlichen Filamentsensor suchen. Bei One+ zusätzlich die ON-Stellung des mechanischen Schalters prüfen."]},{"id":830955,"title":["フィラメントの有無で表示が変わるか試す","Test the reading with and without filament","Zkouška údaje bez filamentu a s filamentem","Anzeige ohne und mit Filament prüfen"],"body":["フィラメントがないときはNINS／1を確認します。入力PTFEからセンサーを通るところまでフィラメントを入れ、INS／2へ変わることを確認してください。NINSは未挿入、INSは挿入です。変化しない場合は作業完了にせず、電源を切って冷却・抜栓してから極性、配線の挟み込み、レバーと光学ゲートの位置を見直します。","With no filament, check for NINS／1. Feed filament through the input PTFE far enough to pass the side sensor and confirm a change to INS／2. NINS means not inserted; INS means inserted. If it does not change, do not mark the repair complete. Switch off, cool and unplug before checking polarity, trapped wiring and lever alignment in the optical gate.","Bez filamentu ověřte NINS／1. Zasuňte filament vstupním PTFE tak daleko, aby prošel bočním senzorem, a ověřte změnu na INS／2. NINS znamená nevložený, INS vložený. Pokud se údaj nemění, opravu neoznačujte za dokončenou. Před kontrolou polarity, sevřených vodičů a páčky v optické bráně tiskárnu vypněte, nechte vychladnout a odpojte.","Ohne Filament NINS／1 prüfen. Filament durch den Eingangs-PTFE bis durch den Seitensensor einführen und den Wechsel auf INS／2 bestätigen. NINS heißt nicht eingeführt, INS eingeführt. Ohne Zustandswechsel die Reparatur nicht abschließen. Vor Prüfung von Polung, eingeklemmten Leitungen und Hebelposition in der Lichtschranke ausschalten, abkühlen lassen und Netzstecker ziehen."]},{"id":830995,"title":["固定と検出を確認して完了する","Finish after securing and testing","Dokončení po kontrole upevnění a funkce","Nach Befestigungs- und Funktionsprüfung abschließen"],"body":["ねじとリベットの戻し忘れ、配線の挟み込み、PTFEの折れがないか確認します。フィラメントの有無でセンサー表示が切り替わり、レバーが戻ることを確かめてから、スプールを戻して通常のロードへ進んでください。","Check for missing screws or rivets, trapped wires and kinked PTFE. Confirm that the sensor reading changes with filament and that the lever returns, then refit the spool and proceed with normal loading.","Zkontrolujte chybějící šrouby a nýty, sevřené vodiče a zalomené PTFE. Ověřte změnu údaje při vložení filamentu i návrat páčky. Poté vraťte cívku a pokračujte běžným zavedením filamentu.","Auf fehlende Schrauben oder Niete, eingeklemmte Kabel und geknickten PTFE achten. Zustandswechsel bei Filament sowie Rückkehr des Hebels prüfen. Danach Spule einsetzen und mit dem normalen Laden fortfahren."]}]};
const references=(family,i)=>{const body=family==='plus'?'sideIRPlusBody':'sideIRR1Body';return[[body,'sideIROldBoard'],['sideIRNewBoard','sideIRM2'],['lcd'],['lcd','bedSupport'],['sideIRHandleRear'],[52,'sideIRRivetPin0'],[body,'sideIROldBoard','sideIRM2'],['sideIRNewBoard'],['sideIRNewBoard','sideIRPlug'],[body,'sideIRNewBoard','sideIRM2'],[52,body],['sideIRHandleRear','sideIRInputTube'],['lcd'],['lcd','sideIRInputTube'],[body,'sideIRInputTube','lcd']][i];};
export const SIDE_IR_SERVICE_TASK={id:'side-ir-replacement',sideIRService:true,category:1,revision:1,title:['側面IRフィラメントセンサーの交換','Replace the side IR filament sensor','Výměna bočního IR senzoru filamentu','Seitlichen IR-Filamentsensor ersetzen'],interval:['基板の交換時','When replacing the board','Při výměně desky','Beim Austausch der Platine'],source:"https://help.prusa3d.com/guide/how-to-replace-the-side-filament-sensor-core-one_408981",get steps(){return BANK[sideIRSelection().family].map((s,i)=>({...s,id:'side-ir-'+s.id,number:i+1,officialId:SIDE_IR_SERVICE_SOURCE.steps[i].id,officialStep:SIDE_IR_SERVICE_SOURCE.steps[i].number,source:SIDE_IR_SERVICE_SOURCE.steps[i].source,wrapperOfficialId:s.id,refs:references(sideIRSelection().family,i),sourcePhotos:SIDE_IR_SERVICE_SOURCE.steps[i].images,supplementalSources:(SIDE_IR_SERVICE_SOURCE.steps[i].supplementalSources||[]).map(r=>({url:r.source||r.url,label:r.label||['関連する公式手順（英語）','Related official step (English)','Související oficiální krok (anglicky)','Zugehöriger offizieller Schritt (Englisch)']})),...(i===2?{firmwareActions:['unload','cooldown']}:i===3?{firmwareActions:['moveZ']}:{})}));}};
